func ProcessoExists(ctx context.Context, exec boil.ContextExecutor, pRCID int) (bool, error) {
	var exists bool
	sql := "select exists(select 1 from `processo` where `prc_id`=? limit 1)"

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, sql)
		fmt.Fprintln(writer, pRCID)
	}
	row := exec.QueryRowContext(ctx, sql, pRCID)

	err := row.Scan(&exists)
	if err != nil {
		return false, errors.Wrap(err, "models: unable to check if processo exists")
	}

	return exists, nil
}

// Exists checks if the Processo row exists.
func (o *Processo) Exists(ctx context.Context, exec boil.ContextExecutor) (bool, error) {
	return ProcessoExists(ctx, exec, o.PRCID)
}
